import{z as s,x as i,o as B,c as d,q as n,j as t,D as a,d as A,s as o,S as l,b as e}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"跨市场联动与传导","description":"","frontmatter":{"title":"跨市场联动与传导","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/obd-crossmarket-linkage.md","filePath":"quant/obd-crossmarket-linkage.md","lastUpdated":1791063341000}'),u={name:"quant/obd-crossmarket-linkage.md"};function p(C,E,F,h,m,c){const r=i("Mermaid");return B(),d("div",null,[E[2]||(E[2]=n('<h1 id="跨市场联动与传导" tabindex="-1">跨市场联动与传导 <a class="header-anchor" href="#跨市场联动与传导" aria-label="Permalink to &quot;跨市场联动与传导&quot;">​</a></h1><div class="epigraph"><p>两个市场一起动，可以是共同信息，也可以是一边的簿事件被人搬到另一边——区分这两件事，靠的不是价格曲线，是追踪搬运工。</p><footer>—— 据 Hasbrouck, Journal of Finance, 1995；Bouchaud 等, Trades, Quotes and Prices, 2018 整理</footer></div><p><a href="/quant/obd-liquidity-common-factors">上一课</a>的共同性还在同一市场的名字之间。本课跨出去：同一标的的多 venue 与期货、现货、ETF 之间的联动传导。主干已有 <a href="/quant/index-arb">指数套利</a>、<a href="/quant/etf-arb">ETF 套利</a>、<a href="/quant/hasbrouck-is">Hasbrouck 信息份额</a>；本课深钻传导的微观渠道——一边的簿事件经由谁、多快、以什么形态出现在另一边的簿上。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>联动不等于传导。两个市场一起动，最小假设是共同信息，更强主张是机械传递——套利流把偏离抹平。不分渠道的代价具体：lead-lag 被读成「期货发现了信息」，其实只是期货表达成本低；流动性收缩被算进资产相关性，其实做市商在两个市场共用同一本库存约束。识别渠道是核心缺口：价格、流量、流动性三条通道各要各自的证据。</p><p><span class="marginnote">术语翻译：lead-lag 就是「先后脚」——A 市场先动、B 市场隔几毫秒跟着动。但先动不等于发现信息：可能只是 A 的表达成本低（保证金少、不占现货篮子），大家习惯先在那里下注，随后才由套利把价格「搬」到 B。</span></p><h3 id="三条通道各自的证据" tabindex="-1">三条通道各自的证据 <a class="header-anchor" href="#三条通道各自的证据" aria-label="Permalink to &quot;三条通道各自的证据&quot;">​</a></h3><p>价格通道：误差修正与协整刻画偏离的收敛速度，<a href="/quant/hasbrouck-is">信息份额</a>式分解把价格发现归到 venue，证据是方差分解。流量通道：套利与对冲订单流本身可观测——ETF 申赎与篮子交易、期现的反向下单——证据是一边的簿事件与另一边的套利流在时延内对应。流动性通道：点差与深度的跨市场联动比价格慢、恢复不对称——冲击后价格先收敛、簿后补厚，证据是微观量的时序差。</p><p><span class="marginnote">毫秒级 lead-lag 结论对时钟同步极其敏感：两个市场的时戳基准差几十毫秒，「谁领先谁」可以整个翻转。先核对<a href="/quant/exchange-broker-clocks">交易所与经纪商时钟</a>的口径，再谈先后——这不是修辞，是数据处理的第一步。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>先立时钟基准：各 venue 的时间戳来源与精度，统一到同一参考，必要时用共同事件（套利成交对）标定偏移。价格层：协整与误差修正给出收敛半衰期；信息份额回答「谁在发现价格」，但份额依赖变量顺序与时延假设。流量层：跨市场的成对订单流（一卖期货、一买篮子）配对追踪，估传导时延与磨损——不是每次偏离都被套利，套利成本决定传导的触发带。流动性层：点差与深度的跨 venue 相关按滞后扫描，确认「价格先、簿后」。三层结论必须相互兼容：流量层的时延应解释价格层的收敛速度与流动性层的补厚滞后。</p>',11)),(B(),t(l,null,{default:a(()=>[o(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20SHOCK%5B%22%E5%B8%82%E5%9C%BA%20A%20%E7%B0%BF%E4%BA%8B%E4%BB%B6%22%5D%20--%3E%20FLOW%5B%22%E5%A5%97%E5%88%A9%2F%E5%AF%B9%E5%86%B2%E8%AE%A2%E5%8D%95%E6%B5%81%22%5D%0A%20%20FLOW%20--%3E%20RESP%5B%22%E5%B8%82%E5%9C%BA%20B%20%E7%B0%BF%E5%93%8D%E5%BA%94%EF%BC%9A%E4%BB%B7%E6%A0%BC%E5%85%88%E5%8A%A8%22%5D%0A%20%20RESP%20--%3E%20CONV%5B%22%E4%BB%B7%E5%B7%AE%E6%94%B6%E6%95%9B%EF%BC%9A%E8%AF%AF%E5%B7%AE%E4%BF%AE%E6%AD%A3%22%5D%0A%20%20CONV%20--%3E%20THICK%5B%22%E6%B7%B1%E5%BA%A6%E8%A1%A5%E5%8E%9A%EF%BC%9A%E6%BB%9E%E5%90%8E%E4%B8%94%E4%B8%8D%E5%AF%B9%E7%A7%B0%22%5D%0A%20%20THICK%20--%3E%20FEED%5B%22%E5%BD%B1%E5%93%8D%20A%20%E4%BE%A7%E5%90%8E%E7%BB%AD%E6%8A%A5%E4%BB%B7%22%5D%0A%20%20CLOCK%5B%22%E6%97%B6%E9%92%9F%E5%9F%BA%E5%87%86%E4%B8%8E%E6%A0%87%E5%AE%9A%22%5D%20--%3E%20FLOW%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[A(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[A("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,"传导的载体是三类人。套利者搬价格：篮子与成分、期货与现货的偏离被他们的订单流抹平，传导速度由套利成本与时延决定，成本高则偏离在带内漂移。做市商搬库存约束：跨市场管理同一本库存，一边吃到的毒性收紧另一边的报价——上一课的共同因子在 venue 间同样成立。授权参与者搬 ETF 的量：申赎机制把 ETF 流量转换成篮子流量，传导强度跟着申赎成本走。三股力叠加，「谁传导给谁」不是常数：常态下期货领导、压力下反向回灌都观测得到。",-1)),E[5]||(E[5]=e("p",null,"三类搬运工各留什么痕迹，可以分看：",-1)),(B(),t(l,null,{default:a(()=>[o(r,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20EVENT%5B%22%E4%B8%80%E8%BE%B9%E5%B8%82%E5%9C%BA%E5%85%88%E5%8A%A8%22%5D%20--%3E%20WHO%7B%22%E8%B0%81%E5%9C%A8%E6%90%AC%E8%BF%90%3F%22%7D%0A%20%20WHO%20--%3E%7C%22%E5%A5%97%E5%88%A9%E8%80%85%22%7C%20C1%5B%22%E6%90%AC%E4%BB%B7%E6%A0%BC%3A%E5%81%8F%E7%A6%BB%E8%A2%AB%E6%88%90%E5%AF%B9%E8%AE%A2%E5%8D%95%E6%8A%B9%E5%B9%B3%22%5D%0A%20%20WHO%20--%3E%7C%22%E5%81%9A%E5%B8%82%E5%95%86%22%7C%20C2%5B%22%E6%90%AC%E7%BA%A6%E6%9D%9F%3A%E4%B8%80%E8%BE%B9%E7%9A%84%E6%AF%92%E6%80%A7%E6%94%B6%E7%B4%A7%E5%8F%A6%E4%B8%80%E8%BE%B9%E6%8A%A5%E4%BB%B7%22%5D%0A%20%20WHO%20--%3E%7C%22%E6%8E%88%E6%9D%83%E5%8F%82%E4%B8%8E%E8%80%85%22%7C%20C3%5B%22%E6%90%AC%E9%87%8F%3A%E7%94%B3%E8%B5%8E%E6%8A%8A%20ETF%20%E6%B5%81%E8%BD%AC%E6%88%90%E7%AF%AE%E5%AD%90%E5%8D%95%22%5D%0A%20%20C1%20--%3E%20T1%5B%22%E7%97%95%E8%BF%B9%3A%E4%B8%A4%E8%BE%B9%E6%97%B6%E5%BB%B6%E5%86%85%E5%87%BA%E7%8E%B0%E9%85%8D%E5%AF%B9%E6%B5%81%22%5D%0A%20%20C2%20--%3E%20T2%5B%22%E7%97%95%E8%BF%B9%3A%E7%82%B9%E5%B7%AE%E8%81%94%E5%8A%A8%2C%E6%85%A2%E4%BA%8E%E4%BB%B7%E6%A0%BC%22%5D%0A%20%20C3%20--%3E%20T3%5B%22%E7%97%95%E8%BF%B9%3A%E5%BC%BA%E5%BA%A6%E8%B7%9F%E9%9A%8F%E7%94%B3%E8%B5%8E%E6%88%90%E6%9C%AC%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[A(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=n('<p><span class="marginnote">数字实例：设套利走一圈的总成本（手续费加冲击加保证金占用）是 5 个基点，那么期货与现货偏离在 ±5bp 之内时没人出手——价格看似「失灵」地各走各的，其实是套利触发带内的正常漂移；带子越宽，联动越迟钝。</span></p><p>错法清单：时戳不对齐就跑因果（方向翻转）；把期现 lead-lag 全读成信息优势（低成本表达与保证金机制同样造成先行）；把 ETF 当独立证券，漏掉申赎通道；把不同 venue 的统计合并口径（内部化、汇总规则）当同质深度。</p><p><span class="marginnote">常见误区：初学者容易把协整当成因果——两个价格总回到同一条线上，不代表谁「导致」谁。协整只说「会回来」，因果证据要靠在流量层看到成对的套利订单：一侧成交后，另一侧在时延内出现方向相反的跟进单。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>传导研究受数据精度硬约束：毫秒以下的结论要求时钟质量超过多数公开数据的能力，超出部分只能存疑。套利流可观测的只是冰山：场内对冲场外的链条在公开数据断线。均衡关系会制度性断裂：涨跌停、熔断与保证金调整会暂时关闭通道，样本单独处理。协整与因子描述收敛，不描述先后因果——因果证据来自流量配对，价格模型只是骨架。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>联动分三条通道：价格（误差修正与信息份额）、流量（套利单配对）、流动性（点差与深度的滞后联动）。</li><li>时钟基准先行：毫秒级「先后」结论对时戳同步极其敏感。</li><li>传导载体三类：套利者搬价格、做市商搬库存约束、授权参与者搬 ETF 申赎。</li><li>次序经验：冲击后价格先收敛、簿后补厚；因果证据来自流量配对，不是协整。</li><li>出处：Hasbrouck, <em>Journal of Finance</em>, 1995；机制与市场语言见 Harris, <em>Trading and Exchanges</em>, 2003；套利通道见<a href="/quant/index-arb">指数套利</a>与<a href="/quant/etf-arb">ETF 套利</a>。</li></ul>',7))])}const b=s(u,[["render",p]]);export{D as __pageData,b as default};
